// Native-array RV32 arithmetic/load-store case. Generated by scripts/build_rtl.py.
// Positive-edge clock; synchronous reset preserves RAM and aborts in-flight work.
// No memory_map is used in the proof import. See spec/revised.txt for the contract.
module case_cpu_memory (
    input  wire          clk,
    input  wire          rst,
    input  wire [1023:0]  reg_init,
    input  wire [31:0]    insn,
    input  wire          insn_valid,
    output wire          insn_ready,
    input  wire          stall_fetch,
    input  wire          stall_decode,
    input  wire          stall_execute,
    input  wire          stall_memory,
    input  wire          stall_writeback,
    input  wire [3:0]     memory_delay,
    output wire          retire_valid,
    output wire [31:0]    retire_insn,
    output wire [31:0]    retire_pc,
    output wire [4:0]     retire_rd,
    output wire [31:0]    retire_value,
    output wire          retire_store,
    output wire [31:0]    retire_address,
    output wire [31:0]    retire_store_data,
    output wire [31:0]    retire_store_mask,
    output wire          trap_valid,
    output wire [2:0]     trap_cause,
    output wire          halted,
    output wire [2:0]     fault_cause,
    output wire [31:0]    arch_pc,
    output wire [4:0]     occupancy,
    output wire [7:0]     stall_reason,
    input  wire [4:0]     debug_reg_addr,
    output wire [31:0]    debug_reg_data,
    input  wire [7:0]     debug_mem_addr,
    output wire [31:0]    debug_mem_data,
    input  wire [3:0]     debug_counter_addr,
    output reg  [31:0]    debug_counter_data
);
    localparam [5:0] OP_ADD = 6'd0;
    localparam [5:0] OP_SUB = 6'd1;
    localparam [5:0] OP_SLL = 6'd2;
    localparam [5:0] OP_SLT = 6'd3;
    localparam [5:0] OP_SLTU = 6'd4;
    localparam [5:0] OP_XOR_ = 6'd5;
    localparam [5:0] OP_SRL = 6'd6;
    localparam [5:0] OP_SRA = 6'd7;
    localparam [5:0] OP_OR_ = 6'd8;
    localparam [5:0] OP_AND_ = 6'd9;
    localparam [5:0] OP_ADDI = 6'd10;
    localparam [5:0] OP_SLTI = 6'd11;
    localparam [5:0] OP_SLTIU = 6'd12;
    localparam [5:0] OP_XORI = 6'd13;
    localparam [5:0] OP_ORI = 6'd14;
    localparam [5:0] OP_ANDI = 6'd15;
    localparam [5:0] OP_SLLI = 6'd16;
    localparam [5:0] OP_SRLI = 6'd17;
    localparam [5:0] OP_SRAI = 6'd18;
    localparam [5:0] OP_LUI = 6'd19;
    localparam [5:0] OP_AUIPC = 6'd20;
    localparam [5:0] OP_MUL = 6'd21;
    localparam [5:0] OP_MULH = 6'd22;
    localparam [5:0] OP_MULHSU = 6'd23;
    localparam [5:0] OP_MULHU = 6'd24;
    localparam [5:0] OP_DIV_ = 6'd25;
    localparam [5:0] OP_DIVU = 6'd26;
    localparam [5:0] OP_REM_ = 6'd27;
    localparam [5:0] OP_REMU = 6'd28;
    localparam [5:0] OP_LB = 6'd29;
    localparam [5:0] OP_LH = 6'd30;
    localparam [5:0] OP_LW = 6'd31;
    localparam [5:0] OP_LBU = 6'd32;
    localparam [5:0] OP_LHU = 6'd33;
    localparam [5:0] OP_SB = 6'd34;
    localparam [5:0] OP_SH = 6'd35;
    localparam [5:0] OP_SW = 6'd36;
    localparam [5:0] OP_FENCE = 6'd37;
    localparam [5:0] OP_INVALID = 6'd63;
    localparam [2:0] FAULT_NONE = 3'd0;
    localparam [2:0] FAULT_LOAD_ALIGN = 3'd1;
    localparam [2:0] FAULT_STORE_ALIGN = 3'd2;
    localparam [2:0] FAULT_LOAD_RANGE = 3'd3;
    localparam [2:0] FAULT_STORE_RANGE = 3'd4;

    // A packet retains the original encoding for retirement, independently of its decode.
    typedef struct packed {
        logic [31:0] instruction;
        logic [5:0]  operation;
        logic [31:0] instruction_pc;
        logic [4:0]  destination;
        logic [31:0] result;
        logic [31:0] address;
        logic [31:0] store_data;
        logic [2:0]  fault;
    } backend_packet_t;

    // Native 1 KiB data memory. Unknown power-on contents are not initialized to zero.
    reg [31:0] ram [0:255];
    reg [1023:0] registers;
    reg [1023:0] next_registers;
    reg [31:0] committed_pc;
    reg [31:0] next_committed_pc;
    reg [2:0] fault;
    reg [2:0] next_fault;
    reg fetch_valid;
    reg next_fetch_valid;
    reg decode_valid;
    reg next_decode_valid;
    reg execute_valid;
    reg next_execute_valid;
    reg memory_valid;
    reg next_memory_valid;
    reg writeback_valid;
    reg next_writeback_valid;
    reg [31:0] fetch_instruction;
    reg [31:0] next_fetch_instruction;
    reg [31:0] decode_instruction;
    reg [31:0] next_decode_instruction;
    backend_packet_t execute_packet;
    backend_packet_t next_execute_packet;
    backend_packet_t memory_packet;
    backend_packet_t next_memory_packet;
    backend_packet_t writeback_packet;
    backend_packet_t next_writeback_packet;
    reg [5:0] execute_remaining;
    reg [5:0] next_execute_remaining;
    reg [3:0] memory_remaining;
    reg [3:0] next_memory_remaining;
    // Strict decode: reserved funct combinations never enter the pipeline.
    function automatic [5:0] decode_operation(input [31:0] word);
        begin
            decode_operation = OP_INVALID;
            case (word[6:0])
                7'h33: begin
                    case (word[31:25])
                        7'h00: begin
                            case (word[14:12])
                                3'd0: decode_operation = OP_ADD;
                                3'd1: decode_operation = OP_SLL;
                                3'd2: decode_operation = OP_SLT;
                                3'd3: decode_operation = OP_SLTU;
                                3'd4: decode_operation = OP_XOR_;
                                3'd5: decode_operation = OP_SRL;
                                3'd6: decode_operation = OP_OR_;
                                3'd7: decode_operation = OP_AND_;
                                default: decode_operation = OP_INVALID;
                            endcase
                        end
                        7'h01: begin
                            case (word[14:12])
                                3'd0: decode_operation = OP_MUL;
                                3'd1: decode_operation = OP_MULH;
                                3'd2: decode_operation = OP_MULHSU;
                                3'd3: decode_operation = OP_MULHU;
                                3'd4: decode_operation = OP_DIV_;
                                3'd5: decode_operation = OP_DIVU;
                                3'd6: decode_operation = OP_REM_;
                                3'd7: decode_operation = OP_REMU;
                                default: decode_operation = OP_INVALID;
                            endcase
                        end
                        7'h20: begin
                            case (word[14:12])
                                3'd0: decode_operation = OP_SUB;
                                3'd5: decode_operation = OP_SRA;
                                default: decode_operation = OP_INVALID;
                            endcase
                        end
                        default: decode_operation = OP_INVALID;
                    endcase
                end
                7'h13: begin
                    case (word[14:12])
                        3'd0: decode_operation = OP_ADDI;
                        3'd2: decode_operation = OP_SLTI;
                        3'd3: decode_operation = OP_SLTIU;
                        3'd4: decode_operation = OP_XORI;
                        3'd6: decode_operation = OP_ORI;
                        3'd7: decode_operation = OP_ANDI;
                        3'd1: begin
                            if (word[31:25] == 7'h00) begin
                                decode_operation = OP_SLLI;
                            end
                        end
                        3'd5: begin
                            case (word[31:25])
                                7'h00: decode_operation = OP_SRLI;
                                7'h20: decode_operation = OP_SRAI;
                                default: decode_operation = OP_INVALID;
                            endcase
                        end
                        default: decode_operation = OP_INVALID;
                    endcase
                end
                7'h37: decode_operation = OP_LUI;
                7'h17: decode_operation = OP_AUIPC;
                7'h03: begin
                    case (word[14:12])
                        3'd0: decode_operation = OP_LB;
                        3'd1: decode_operation = OP_LH;
                        3'd2: decode_operation = OP_LW;
                        3'd4: decode_operation = OP_LBU;
                        3'd5: decode_operation = OP_LHU;
                        default: decode_operation = OP_INVALID;
                    endcase
                end
                7'h23: begin
                    case (word[14:12])
                        3'd0: decode_operation = OP_SB;
                        3'd1: decode_operation = OP_SH;
                        3'd2: decode_operation = OP_SW;
                        default: decode_operation = OP_INVALID;
                    endcase
                end
                7'h0f: begin
                    if (word[14:12] == 3'd0 && word[11:7] == 0 && word[19:15] == 0) begin
                        decode_operation = OP_FENCE;
                    end
                end
                default: decode_operation = OP_INVALID;
            endcase
        end
    endfunction

    function automatic [31:0] decode_immediate(input [31:0] word);
        begin
            case (word[6:0])
                7'h37, 7'h17: begin
                    decode_immediate = {word[31:12], 12'b0};
                end
                7'h23: begin
                    decode_immediate = {{20{word[31]}}, word[31:25], word[11:7]};
                end
                default: begin
                    decode_immediate = {{20{word[31]}}, word[31:20]};
                end
            endcase
        end
    endfunction

    function automatic is_load(input [5:0] operation);
        begin
            case (operation)
                OP_LB, OP_LH, OP_LW, OP_LBU, OP_LHU: is_load = 1'b1;
                default: is_load = 1'b0;
            endcase
        end
    endfunction

    function automatic is_store(input [5:0] operation);
        begin
            case (operation)
                OP_SB, OP_SH, OP_SW: is_store = 1'b1;
                default: is_store = 1'b0;
            endcase
        end
    endfunction

    function automatic is_barrier(input [5:0] operation);
        begin
            is_barrier = is_load(operation) || is_store(operation) || operation == OP_FENCE;
        end
    endfunction

    function automatic [4:0] decode_destination(input [31:0] word, input [5:0] operation);
        begin
            if (is_store(operation) || operation == OP_FENCE) begin
                decode_destination = 5'd0;
            end else begin
                decode_destination = word[11:7];
            end
        end
    endfunction

    function automatic [5:0] execution_wait(input [5:0] operation);
        begin
            case (operation)
                OP_MUL, OP_MULH, OP_MULHSU, OP_MULHU: execution_wait = 6'd2;
                OP_DIV_, OP_DIVU, OP_REM_, OP_REMU: execution_wait = 6'd33;
                default: execution_wait = 6'd0;
            endcase
        end
    endfunction

    // Integer arithmetic is independent of the Lean transaction implementation.
    function automatic [31:0] arithmetic_result(
        input [5:0] operation,
        input [31:0] left,
        input [31:0] right,
        input [31:0] immediate,
        input [31:0] instruction_pc
    );
        reg signed [63:0] signed_left;
        reg signed [63:0] signed_right;
        reg signed [63:0] unsigned_right;
        reg signed [63:0] signed_product;
        reg [63:0] unsigned_left;
        reg [63:0] unsigned_product;
        begin
            signed_left = {{32{left[31]}}, left};
            signed_right = {{32{right[31]}}, right};
            unsigned_right = {32'b0, right};
            unsigned_left = {32'b0, left};
            signed_product = 64'b0;
            unsigned_product = 64'b0;
            arithmetic_result = 32'b0;
            case (operation)
                OP_ADD: begin
                    arithmetic_result = left + right;
                end
                OP_SUB: begin
                    arithmetic_result = left - right;
                end
                OP_SLL: begin
                    arithmetic_result = left << right[4:0];
                end
                OP_SLT: begin
                    arithmetic_result = $signed(left) < $signed(right);
                end
                OP_SLTU: begin
                    arithmetic_result = left < right;
                end
                OP_XOR_: begin
                    arithmetic_result = left ^ right;
                end
                OP_SRL: begin
                    arithmetic_result = left >> right[4:0];
                end
                OP_SRA: begin
                    arithmetic_result = $signed(left) >>> right[4:0];
                end
                OP_OR_: begin
                    arithmetic_result = left | right;
                end
                OP_AND_: begin
                    arithmetic_result = left & right;
                end
                OP_ADDI: begin
                    arithmetic_result = left + immediate;
                end
                OP_SLTI: begin
                    arithmetic_result = $signed(left) < $signed(immediate);
                end
                OP_SLTIU: begin
                    arithmetic_result = left < immediate;
                end
                OP_XORI: begin
                    arithmetic_result = left ^ immediate;
                end
                OP_ORI: begin
                    arithmetic_result = left | immediate;
                end
                OP_ANDI: begin
                    arithmetic_result = left & immediate;
                end
                OP_SLLI: begin
                    arithmetic_result = left << immediate[4:0];
                end
                OP_SRLI: begin
                    arithmetic_result = left >> immediate[4:0];
                end
                OP_SRAI: begin
                    arithmetic_result = $signed(left) >>> immediate[4:0];
                end
                OP_LUI: begin
                    arithmetic_result = immediate;
                end
                OP_AUIPC: begin
                    arithmetic_result = instruction_pc + immediate;
                end
                OP_MUL: begin
                    arithmetic_result = left * right;
                end
                OP_MULH: begin
                    signed_product = signed_left * signed_right;
                    arithmetic_result = signed_product[63:32];
                end
                OP_MULHSU: begin
                    signed_product = signed_left * unsigned_right;
                    arithmetic_result = signed_product[63:32];
                end
                OP_MULHU: begin
                    unsigned_product = unsigned_left * {32'b0, right};
                    arithmetic_result = unsigned_product[63:32];
                end
                OP_DIV_: begin
                    if (right == 0) begin
                        arithmetic_result = 32'hffffffff;
                    end else if (left == 32'h80000000 && right == 32'hffffffff) begin
                        arithmetic_result = left;
                    end else begin
                        arithmetic_result = $signed(left) / $signed(right);
                    end
                end
                OP_DIVU: begin
                    if (right == 0) begin
                        arithmetic_result = 32'hffffffff;
                    end else begin
                        arithmetic_result = left / right;
                    end
                end
                OP_REM_: begin
                    if (right == 0) begin
                        arithmetic_result = left;
                    end else if (left == 32'h80000000 && right == 32'hffffffff) begin
                        arithmetic_result = 32'b0;
                    end else begin
                        arithmetic_result = $signed(left) % $signed(right);
                    end
                end
                OP_REMU: begin
                    if (right == 0) begin
                        arithmetic_result = left;
                    end else begin
                        arithmetic_result = left % right;
                    end
                end
                default: begin
                    arithmetic_result = 32'b0;
                end
            endcase
        end
    endfunction

    function automatic [2:0] memory_fault(input [5:0] operation, input [31:0] address);
        reg misaligned;
        begin
            misaligned = 1'b0;
            case (operation)
                OP_LH, OP_LHU, OP_SH: begin
                    misaligned = address[0];
                end
                OP_LW, OP_SW: begin
                    misaligned = |address[1:0];
                end
                default: begin
                    misaligned = 1'b0;
                end
            endcase
            memory_fault = FAULT_NONE;
            if (is_load(operation) || is_store(operation)) begin
                if (misaligned) begin
                    if (is_store(operation)) begin
                        memory_fault = FAULT_STORE_ALIGN;
                    end else begin
                        memory_fault = FAULT_LOAD_ALIGN;
                    end
                end else if (|address[31:10]) begin
                    if (is_store(operation)) begin
                        memory_fault = FAULT_STORE_RANGE;
                    end else begin
                        memory_fault = FAULT_LOAD_RANGE;
                    end
                end
            end
        end
    endfunction

    function automatic [31:0] load_result(
        input [5:0] operation,
        input [31:0] address,
        input [31:0] memory_word
    );
        reg [31:0] selected;
        begin
            selected = memory_word >> {address[1:0], 3'b0};
            case (operation)
                OP_LB: begin
                    load_result = {{24{selected[7]}}, selected[7:0]};
                end
                OP_LBU: begin
                    load_result = {24'b0, selected[7:0]};
                end
                OP_LH: begin
                    load_result = {{16{selected[15]}}, selected[15:0]};
                end
                OP_LHU: begin
                    load_result = {16'b0, selected[15:0]};
                end
                OP_LW: begin
                    load_result = memory_word;
                end
                default: begin
                    load_result = 32'b0;
                end
            endcase
        end
    endfunction

    function automatic [31:0] store_mask(input [5:0] operation, input [31:0] address);
        begin
            case (operation)
                OP_SB: begin
                    store_mask = 32'h000000ff << {address[1:0], 3'b0};
                end
                OP_SH: begin
                    store_mask = 32'h0000ffff << {address[1:0], 3'b0};
                end
                OP_SW: begin
                    store_mask = 32'hffffffff;
                end
                default: begin
                    store_mask = 32'b0;
                end
            endcase
        end
    endfunction

    function automatic [31:0] shifted_store_data(input [31:0] data, input [31:0] address);
        begin
            shifted_store_data = data << {address[1:0], 3'b0};
        end
    endfunction

    // Independent native-array read ports. Their addresses use old registers/inputs.
    wire [31:0] memory_read_word = ram[memory_packet.address[9:2]];
    wire [31:0] writeback_old_word = ram[writeback_packet.address[9:2]];
    assign debug_mem_data = ram[debug_mem_addr];
    wire [31:0] writeback_mask = store_mask(writeback_packet.operation, writeback_packet.address);
    wire [31:0] writeback_shifted_data = shifted_store_data(writeback_packet.store_data, writeback_packet.address);
    wire [31:0] writeback_new_word =
        (writeback_old_word & ~writeback_mask) | (writeback_shifted_data & writeback_mask);
    wire writeback_fire = !rst && fault == FAULT_NONE && writeback_valid && !stall_writeback;
    wire store_commit = writeback_fire && writeback_packet.fault == FAULT_NONE && is_store(writeback_packet.operation);
    wire fault_commit = writeback_fire && writeback_packet.fault != FAULT_NONE;

    // RAM state changes only here. Reset inhibits a write but never clears the array.
    always @(posedge clk) begin
        if (store_commit) begin
            ram[writeback_packet.address[9:2]] <= writeback_new_word;
        end
    end

    // Retirement outputs describe the old WB packet, before the edge transfers slots.
    assign retire_valid = writeback_fire;
    assign retire_insn = writeback_fire ? writeback_packet.instruction : 32'b0;
    assign retire_pc = writeback_fire ? writeback_packet.instruction_pc : 32'b0;
    assign retire_rd = writeback_fire ? writeback_packet.destination : 5'b0;
    assign retire_value = writeback_fire ? writeback_packet.result : 32'b0;
    assign retire_store = store_commit;
    assign retire_address = writeback_fire ? writeback_packet.address : 32'b0;
    assign retire_store_data = store_commit ? writeback_shifted_data : 32'b0;
    assign retire_store_mask = store_commit ? writeback_mask : 32'b0;
    assign trap_valid = fault_commit;
    assign trap_cause = fault_commit ? writeback_packet.fault : FAULT_NONE;
    assign halted = fault != FAULT_NONE;
    assign fault_cause = fault;
    assign arch_pc = committed_pc;
    assign occupancy = {writeback_valid, memory_valid, execute_valid, decode_valid, fetch_valid};
    assign debug_reg_data = debug_reg_addr == 0 ? 32'b0 : registers[32*debug_reg_addr +: 32];

    reg [5:0] issue_operation;
    reg [4:0] issue_rd;
    reg [4:0] issue_rs1;
    reg [4:0] issue_rs2;
    reg [31:0] issue_left;
    reg [31:0] issue_right;
    reg [31:0] issue_immediate;
    reg [31:0] issue_address;
    reg [31:0] issue_pc;
    reg issue_blocked;
    reg issue_fire;
    reg next_ready;
    // Each diagnostic bit has a distinct operational reason and is tested in regression.
    assign stall_reason[0] = stall_fetch;
    assign stall_reason[1] = stall_decode;
    assign stall_reason[2] = stall_execute;
    assign stall_reason[3] = stall_memory;
    assign stall_reason[4] = stall_writeback;
    assign stall_reason[5] = execute_valid && execute_remaining != 0;
    assign stall_reason[6] = memory_valid && memory_remaining != 0;
    assign stall_reason[7] = halted || (decode_valid && issue_blocked);
    assign insn_ready = next_ready;

    always @* begin
        next_registers = registers;
        next_committed_pc = committed_pc;
        next_fault = fault;
        next_fetch_valid = fetch_valid;
        next_decode_valid = decode_valid;
        next_execute_valid = execute_valid;
        next_memory_valid = memory_valid;
        next_writeback_valid = writeback_valid;
        next_fetch_instruction = fetch_instruction;
        next_decode_instruction = decode_instruction;
        next_execute_packet = execute_packet;
        next_memory_packet = memory_packet;
        next_writeback_packet = writeback_packet;
        next_execute_remaining = execute_remaining;
        next_memory_remaining = memory_remaining;
        issue_operation = OP_INVALID;
        issue_rd = 5'b0;
        issue_rs1 = 5'b0;
        issue_rs2 = 5'b0;
        issue_left = 32'b0;
        issue_right = 32'b0;
        issue_immediate = 32'b0;
        issue_address = 32'b0;
        issue_pc = 32'b0;
        issue_blocked = 1'b0;
        issue_fire = 1'b0;
        next_ready = 1'b0;

        // WB: precise architectural effects. Faults retire once, then halt and flush.
        if (writeback_fire) begin
            if (writeback_packet.fault != FAULT_NONE) begin
                next_fault = writeback_packet.fault;
                next_fetch_valid = 1'b0;
                next_decode_valid = 1'b0;
                next_execute_valid = 1'b0;
                next_memory_valid = 1'b0;
                next_writeback_valid = 1'b0;
                next_fetch_instruction = 32'b0;
                next_decode_instruction = 32'b0;
                next_execute_packet = '0;
                next_memory_packet = '0;
                next_writeback_packet = '0;
                next_execute_remaining = 6'b0;
                next_memory_remaining = 4'b0;
            end else begin
                if (writeback_packet.destination != 0) begin
                    next_registers[32*writeback_packet.destination +: 32] = writeback_packet.result;
                end
                next_committed_pc = committed_pc + 32'd4;
                next_writeback_valid = 1'b0;
            end
        end

        if (next_fault == FAULT_NONE) begin
            // MEM: the native RAM is read here. Countdown is sampled at EX->MEM.
            if (!stall_memory) begin
                if (memory_remaining != 0) begin
                    next_memory_remaining = memory_remaining - 4'd1;
                end else if (!next_writeback_valid) begin
                    next_writeback_packet = memory_packet;
                    if (is_load(memory_packet.operation) && memory_packet.fault == FAULT_NONE) begin
                        next_writeback_packet.result = load_result(
                            memory_packet.operation,
                            memory_packet.address,
                            memory_read_word
                        );
                    end
                    next_writeback_valid = memory_valid;
                    next_memory_valid = 1'b0;
                end
            end

            // EX: independent execution stall and multicycle arithmetic countdown.
            if (!stall_execute) begin
                if (execute_remaining != 0) begin
                    next_execute_remaining = execute_remaining - 6'd1;
                end else if (!next_memory_valid) begin
                    next_memory_packet = execute_packet;
                    next_memory_valid = execute_valid;
                    next_execute_valid = 1'b0;
                    if (execute_valid && is_barrier(execute_packet.operation)) begin
                        next_memory_remaining = memory_delay;
                    end else begin
                        next_memory_remaining = 4'b0;
                    end
                end
            end

            // ID: arithmetic may overlap; loads/stores/FENCE serialize the backend.
            if (!stall_decode && !next_execute_valid && decode_valid) begin
                issue_operation = decode_operation(decode_instruction);
                issue_blocked =
                    (next_memory_valid && is_barrier(next_memory_packet.operation)) ||
                    (next_writeback_valid && is_barrier(next_writeback_packet.operation)) ||
                    (is_barrier(issue_operation) && (next_memory_valid || next_writeback_valid));
                if (!issue_blocked) begin
                    issue_fire = 1'b1;
                    issue_rd = decode_destination(decode_instruction, issue_operation);
                    issue_rs1 = decode_instruction[19:15];
                    issue_rs2 = decode_instruction[24:20];
                    issue_immediate = decode_immediate(decode_instruction);
                    if (issue_rs1 != 0) begin
                        issue_left = next_registers[32*issue_rs1 +: 32];
                    end
                    if (issue_rs2 != 0) begin
                        issue_right = next_registers[32*issue_rs2 +: 32];
                    end

                    // WB forwarding precedes younger MEM forwarding.
                    if (next_writeback_valid && next_writeback_packet.destination != 0) begin
                        if (next_writeback_packet.destination == issue_rs1) begin
                            issue_left = next_writeback_packet.result;
                        end
                        if (next_writeback_packet.destination == issue_rs2) begin
                            issue_right = next_writeback_packet.result;
                        end
                    end
                    if (next_memory_valid && next_memory_packet.destination != 0) begin
                        if (next_memory_packet.destination == issue_rs1) begin
                            issue_left = next_memory_packet.result;
                        end
                        if (next_memory_packet.destination == issue_rs2) begin
                            issue_right = next_memory_packet.result;
                        end
                    end

                    issue_pc = next_committed_pc;
                    if (next_writeback_valid) begin
                        issue_pc = issue_pc + 32'd4;
                    end
                    if (next_memory_valid) begin
                        issue_pc = issue_pc + 32'd4;
                    end
                    issue_address = issue_left + issue_immediate;
                    next_execute_packet.instruction = decode_instruction;
                    next_execute_packet.operation = issue_operation;
                    next_execute_packet.instruction_pc = issue_pc;
                    next_execute_packet.destination = issue_rd;
                    next_execute_packet.result = arithmetic_result(
                        issue_operation,
                        issue_left,
                        issue_right,
                        issue_immediate,
                        issue_pc
                    );
                    next_execute_packet.address = issue_address;
                    next_execute_packet.store_data = issue_right;
                    next_execute_packet.fault = memory_fault(issue_operation, issue_address);
                    next_execute_valid = 1'b1;
                    next_decode_valid = 1'b0;
                    next_execute_remaining = execution_wait(issue_operation);
                end
            end

            // IF->ID and input acceptance may reuse capacity freed on this edge.
            if (!next_decode_valid) begin
                next_decode_instruction = fetch_instruction;
                next_decode_valid = fetch_valid;
                next_fetch_valid = 1'b0;
            end
            next_ready = !rst && !stall_fetch && !next_fetch_valid &&
                decode_operation(insn) != OP_INVALID;
            if (insn_valid && next_ready) begin
                next_fetch_instruction = insn;
                next_fetch_valid = 1'b1;
            end
        end
    end

    // State updates are simultaneous; all right-hand sides above are pre-edge data.
    always @(posedge clk) begin
        if (rst) begin
            registers <= {reg_init[1023:32], 32'b0};
            committed_pc <= 32'b0;
            fault <= FAULT_NONE;
            fetch_valid <= 1'b0;
            decode_valid <= 1'b0;
            execute_valid <= 1'b0;
            memory_valid <= 1'b0;
            writeback_valid <= 1'b0;
            fetch_instruction <= 32'b0;
            decode_instruction <= 32'b0;
            execute_packet <= '0;
            memory_packet <= '0;
            writeback_packet <= '0;
            execute_remaining <= 6'b0;
            memory_remaining <= 4'b0;
        end else begin
            registers <= next_registers;
            committed_pc <= next_committed_pc;
            fault <= next_fault;
            fetch_valid <= next_fetch_valid;
            decode_valid <= next_decode_valid;
            execute_valid <= next_execute_valid;
            memory_valid <= next_memory_valid;
            writeback_valid <= next_writeback_valid;
            fetch_instruction <= next_fetch_instruction;
            decode_instruction <= next_decode_instruction;
            execute_packet <= next_execute_packet;
            memory_packet <= next_memory_packet;
            writeback_packet <= next_writeback_packet;
            execute_remaining <= next_execute_remaining;
            memory_remaining <= next_memory_remaining;
        end
    end

    // Observability counters wrap modulo 2^32; RAM and ISA state are unaffected.
    reg [31:0] count_cycles;
    reg [31:0] count_retired;
    reg [31:0] count_loads;
    reg [31:0] count_stores;
    reg [31:0] count_traps;
    reg [31:0] count_fetch_stalls;
    reg [31:0] count_decode_stalls;
    reg [31:0] count_execute_stalls;
    reg [31:0] count_memory_stalls;
    reg [31:0] count_writeback_stalls;
    reg [31:0] count_memory_waits;
    reg [31:0] count_barrier_stalls;
    always @* begin
        case (debug_counter_addr)
            4'd0: debug_counter_data = count_cycles;
            4'd1: debug_counter_data = count_retired;
            4'd2: debug_counter_data = count_loads;
            4'd3: debug_counter_data = count_stores;
            4'd4: debug_counter_data = count_traps;
            4'd5: debug_counter_data = count_fetch_stalls;
            4'd6: debug_counter_data = count_decode_stalls;
            4'd7: debug_counter_data = count_execute_stalls;
            4'd8: debug_counter_data = count_memory_stalls;
            4'd9: debug_counter_data = count_writeback_stalls;
            4'd10: debug_counter_data = count_memory_waits;
            4'd11: debug_counter_data = count_barrier_stalls;
            default: debug_counter_data = 32'b0;
        endcase
    end
    always @(posedge clk) begin
        if (rst) begin
            count_cycles <= 32'b0;
        end else if (1'b1) begin
            count_cycles <= count_cycles + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_retired <= 32'b0;
        end else if (writeback_fire) begin
            count_retired <= count_retired + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_loads <= 32'b0;
        end else if (writeback_fire && !fault_commit && is_load(writeback_packet.operation)) begin
            count_loads <= count_loads + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_stores <= 32'b0;
        end else if (store_commit) begin
            count_stores <= count_stores + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_traps <= 32'b0;
        end else if (fault_commit) begin
            count_traps <= count_traps + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_fetch_stalls <= 32'b0;
        end else if (fetch_valid && stall_fetch) begin
            count_fetch_stalls <= count_fetch_stalls + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_decode_stalls <= 32'b0;
        end else if (decode_valid && stall_decode) begin
            count_decode_stalls <= count_decode_stalls + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_execute_stalls <= 32'b0;
        end else if (execute_valid && stall_execute) begin
            count_execute_stalls <= count_execute_stalls + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_memory_stalls <= 32'b0;
        end else if (memory_valid && stall_memory) begin
            count_memory_stalls <= count_memory_stalls + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_writeback_stalls <= 32'b0;
        end else if (writeback_valid && stall_writeback) begin
            count_writeback_stalls <= count_writeback_stalls + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_memory_waits <= 32'b0;
        end else if (memory_valid && memory_remaining != 0) begin
            count_memory_waits <= count_memory_waits + 32'd1;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            count_barrier_stalls <= 32'b0;
        end else if (decode_valid && issue_blocked) begin
            count_barrier_stalls <= count_barrier_stalls + 32'd1;
        end
    end

`ifdef FORMAL
`ifndef PROPERTY
`define PROPERTY 0
`endif
    reg formal_past_valid;
    initial formal_past_valid = 1'b0;
    always @(posedge clk) begin
        formal_past_valid <= 1'b1;
        if (!formal_past_valid) begin
            assume(rst && formal_ram_init_equal);
        end
        if (formal_past_valid) begin
            assert(registers[31:0] == 32'b0);
            assert(debug_reg_addr != 0 || debug_reg_data == 32'b0);
            assert(!(rst && retire_valid));
            assert(!(rst && store_commit));
            assert(!(rst && insn_ready));
            assert(!stall_writeback || !retire_valid);
            assert(!stall_fetch || !insn_ready);
            assert(!halted || !retire_valid);
            assert(!halted || !insn_ready);
            assert(!halted || occupancy == 5'b0);
            assert(!store_commit || writeback_valid);
            assert(!store_commit || writeback_packet.fault == FAULT_NONE);
            assert(!store_commit || is_store(writeback_packet.operation));
            assert(!trap_valid || retire_valid);
            assert(!trap_valid || !retire_store);
            assert(!trap_valid || trap_cause != FAULT_NONE);
            assert(!retire_store || retire_store_mask != 32'b0);
            assert(!retire_store || retire_address[31:10] == 0);
            assert(!retire_valid || decode_operation(retire_insn) != OP_INVALID);
            assert(!execute_valid || decode_operation(execute_packet.instruction) == execute_packet.operation);
            assert(!memory_valid || decode_operation(memory_packet.instruction) == memory_packet.operation);
            assert(!writeback_valid || decode_operation(writeback_packet.instruction) == writeback_packet.operation);
            if (execute_valid && is_barrier(execute_packet.operation)) begin
                assert(!memory_valid);
                assert(!writeback_valid);
            end
            if (memory_valid && is_barrier(memory_packet.operation)) begin
                assert(!execute_valid);
                assert(!writeback_valid);
            end
            if (writeback_valid && is_barrier(writeback_packet.operation)) begin
                assert(!execute_valid);
                assert(!memory_valid);
            end
            if ($past(rst)) begin
                assert(occupancy == 5'b0);
                assert(committed_pc == 32'b0);
                assert(fault == FAULT_NONE);
                assert(registers == {$past(reg_init[1023:32]),32'b0});
                assert(execute_remaining == 0);
                assert(memory_remaining == 0);
            end
            if (!$past(rst)) begin
                if ($past(writeback_valid && stall_writeback && !halted)) begin
                    assert(writeback_valid);
                    assert(writeback_packet == $past(writeback_packet));
                    assert(committed_pc == $past(committed_pc));
                    assert(registers == $past(registers));
                end
                if ($past(memory_valid && stall_memory && !halted)) begin
                    assert(memory_valid);
                    assert(memory_packet == $past(memory_packet));
                    assert(memory_remaining == $past(memory_remaining));
                end
                if ($past(execute_valid && stall_execute && !halted)) begin
                    assert(execute_valid);
                    assert(execute_packet == $past(execute_packet));
                    assert(execute_remaining == $past(execute_remaining));
                end
                if ($past(fault_commit)) begin
                    assert(halted);
                    assert(fault == $past(writeback_packet.fault));
                    assert(committed_pc == $past(committed_pc));
                    assert(registers == $past(registers));
                    assert(occupancy == 0);
                end
                if ($past(writeback_fire && !fault_commit)) begin
                    assert(committed_pc == $past(committed_pc) + 32'd4);
                end
                if ($past(halted)) begin
                    assert(halted);
                    assert(fault == $past(fault));
                    assert(committed_pc == $past(committed_pc));
                    assert(registers == $past(registers));
                end
                if ($past(store_commit && writeback_packet.operation == OP_SW)) begin
                    assert($past(writeback_mask) == 32'hffffffff);
                end
                if ($past(store_commit && writeback_packet.operation == OP_SB)) begin
                    assert($past(writeback_mask) == (32'h000000ff << {$past(writeback_packet.address[1:0]),3'b0}));
                end
                if ($past(store_commit && writeback_packet.operation == OP_SH)) begin
                    assert($past(writeback_packet.address[0]) == 1'b0);
                    assert($past(writeback_mask) == (32'h0000ffff << {$past(writeback_packet.address[1:0]),3'b0}));
                end
            end
        end
    end
`include "memory_reference.svh"
`endif
endmodule
